<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api,type ApiResponse,type Review}from'@whaashop/shared';interface Append{id:number;sequenceNo:number;content:string;imagesJson:string;createdAt:string}interface ReviewView{review:Review;appends:Append[]}const rows=ref<ReviewView[]>([]),selected=ref<ReviewView>(),dialog=ref(false),message=ref('');const form=reactive({content:'',images:[]as string[]});async function load(){rows.value=(await api.get<ApiResponse<ReviewView[]>>('/shop/reviews/mine')).data.data}function append(v:ReviewView){selected.value=v;form.content='';form.images=[];message.value='';dialog.value=true}async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file||form.images.length>=9)return;const data=new FormData();data.append('file',file);const res=await api.post<ApiResponse<{url:string}>>('/shop/files/review-images',data);form.images.push(res.data.data.url)}async function submit(){if(!selected.value)return;await api.post(`/shop/reviews/${selected.value.review.id}/appends`,form);message.value='追评发布成功';dialog.value=false;load()}function pics(raw:string){try{return JSON.parse(raw)as string[]}catch{return[]}}onMounted(load)</script>
<template><div class="container reviews-page"><div class="page-heading"><div><span>MY REVIEWS</span><h1>我的评价</h1><p>记录每一次真实的购物感受</p></div><div class="review-count"><b>{{rows.length}}</b><span>条评价</span></div></div><div class="review-list"><article v-for="v in rows" :key="v.review.id" class="my-review"><header><router-link :to="`/products/${v.review.productId}`">商品 #{{v.review.productId}}</router-link><span :class="{hidden:v.review.hidden}">{{v.review.hidden?'已隐藏':'展示中'}}</span></header><div class="review-main"><div class="stars">{{'★'.repeat(v.review.rating)}}{{'☆'.repeat(5-v.review.rating)}}</div><p>{{v.review.content}}</p><div class="review-pics"><img v-for="img in pics(v.review.imagesJson)" :key="img" :src="img"></div><small>{{new Date(v.review.createdAt).toLocaleString()}}</small></div><div v-for="a in v.appends" :key="a.id" class="append-item"><b>第 {{a.sequenceNo}} 次追评</b><p>{{a.content}}</p><div class="review-pics"><img v-for="img in pics(a.imagesJson)" :key="img" :src="img"></div><small>{{new Date(a.createdAt).toLocaleString()}}</small></div><footer><span>已追评 {{v.review.appendCount}} / 3 次</span><button v-if="v.review.appendCount<3&&!v.review.hidden" @click="append(v)">继续追评 →</button><em v-else-if="v.review.appendCount>=3">已达到追评上限</em></footer></article></div><div v-if="!rows.length" class="empty"><b>☆</b><h3>还没有发表评价</h3><p>确认收货后，可以在订单页面评价商品</p><router-link class="btn" to="/orders">查看我的订单</router-link></div></div><dialog :open="dialog" class="append-dialog"><button class="close" @click="dialog=false">×</button><span>FOLLOW-UP REVIEW</span><h2>追加评价</h2><p>第 {{(selected?.review.appendCount||0)+1}} 次追评，还可以追评 {{3-(selected?.review.appendCount||0)}} 次</p><form @submit.prevent="submit"><textarea v-model="form.content" rows="5" maxlength="2000" required placeholder="使用一段时间后，商品体验怎么样？"></textarea><div class="upload-row"><label>＋ 添加图片<input type="file" hidden accept="image/jpeg,image/png,image/webp" @change="upload"></label><small>{{form.images.length}} / 9</small></div><div class="preview"><div v-for="(img,i) in form.images" :key="img"><img :src="img"><button type="button" @click="form.images.splice(i,1)">×</button></div></div><button class="btn submit">发布追评</button></form></dialog></template>
<style scoped>.reviews-page{padding:36px 0 70px}.page-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.page-heading>div>span,.append-dialog>span{color:#f97316;font-size:11px;letter-spacing:2px;font-weight:800}.page-heading h1{font-size:34px;margin:5px 0}.page-heading p{margin:0;color:#967866}.review-count{width:85px;height:85px;border-radius:50%;display:grid;place-content:center;text-align:center;background:#fff2e6;border:5px solid #ffedd5}.review-count b{font-size:23px;color:#ea580c}.review-count span{font-size:10px;color:#967866}.review-list{display:grid;gap:17px}.my-review{background:#fff;border:1px solid #f1e2d7;border-radius:18px;padding:22px;box-shadow:0 9px 27px #9a34110b}.my-review>header,.my-review>footer{display:flex;justify-content:space-between;align-items:center}.my-review>header{border-bottom:1px solid #f3e7df;padding-bottom:14px}.my-review>header a{font-weight:800;color:#624737;text-decoration:none}.my-review>header span{font-size:11px;color:#15803d;background:#f0fdf4;padding:5px 9px;border-radius:99px}.my-review>header span.hidden{color:#dc2626;background:#fef2f2}.review-main{padding:18px 0}.review-main small,.append-item small{color:#a88772}.review-pics{display:flex;gap:8px;margin:10px 0}.review-pics img{width:75px;height:75px;border-radius:9px;object-fit:cover}.append-item{margin:8px 0;padding:15px 18px;border-left:3px solid #fb923c;background:#fff8f2;border-radius:0 10px 10px 0}.append-item b{color:#c2410c;font-size:12px}.my-review>footer{border-top:1px solid #f3e7df;padding-top:14px;color:#967866;font-size:12px}.my-review>footer button{border:0;background:none;color:#ea580c;font-weight:800;cursor:pointer}.my-review>footer em{font-style:normal}.empty{text-align:center;padding:70px}.empty>b{font-size:55px;color:#fdba74}.empty .btn{display:inline-block;text-decoration:none;margin-top:10px}.append-dialog{width:min(570px,92vw);border:0;border-radius:20px;padding:30px;box-shadow:0 25px 70px #7c2d1240}.append-dialog .close{float:right;border:0;background:#fff2e6;width:32px;height:32px;border-radius:50%;font-size:20px}.append-dialog>p{color:#967866}.append-dialog textarea{width:100%;padding:13px;border:1px solid #ead8ca;border-radius:10px;font:inherit}.upload-row{display:flex;justify-content:space-between;align-items:center;margin:13px 0}.upload-row label{padding:9px 14px;border:1px dashed #fb923c;border-radius:9px;color:#c2410c;cursor:pointer}.upload-row small{color:#967866}.preview{display:flex;gap:8px;flex-wrap:wrap}.preview>div{position:relative}.preview img{width:70px;height:70px;border-radius:8px;object-fit:cover}.preview button{position:absolute;right:-5px;top:-5px;border:0;border-radius:50%;background:#7c2d12;color:#fff}.submit{width:100%;margin-top:18px}.stars{color:#f59e0b}@media(max-width:600px){.page-heading{align-items:start}.my-review{padding:16px}}</style>
